// Woorkzi Fikir Yönetim Uygulaması - Ana Component
import React, { useState, useEffect } from 'react';
import { 
  Lightbulb, 
  Plus, 
  Search, 
  Filter,
  ChevronDown,
  ChevronUp,
  Calendar,
  Users,
  Clock,
  Target,
  Zap,
  FolderPlus,
  CheckCircle,
  Circle,
  PlayCircle
} from 'lucide-react';

// Veri ve stiller
import { 
  mockIdeas, 
  mockTasks, 
  categories, 
  statusOptions, 
  priorityOptions,
  createNewIdea,
  createNewTask,
  getSubIdeas,
  getTasksByIdeaId
} from './data/mockData';
import { validateIdea, ToastManager, formatCharCount } from './utils/validation';
import { AddSubIdeaModal, AddTaskModal } from './components/Modal';
import './App.css';

function App() {
  // State yönetimi
  const [ideas, setIdeas] = useState(mockIdeas);
  const [tasks, setTasks] = useState(mockTasks);
  const [expandedIdea, setExpandedIdea] = useState(null);
  const [showAddForm, setShowAddForm] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('all');
  const [filterStatus, setFilterStatus] = useState('all');
  
  // Yeni fikir formu state'i
  const [newIdea, setNewIdea] = useState({
    title: '',
    description: '',
    category: 'other',
    priority: 'medium'
  });
  const [formErrors, setFormErrors] = useState({});
  
  // Modal state'leri
  const [showSubIdeaModal, setShowSubIdeaModal] = useState(false);
  const [showTaskModal, setShowTaskModal] = useState(false);
  const [currentIdeaForModal, setCurrentIdeaForModal] = useState(null);

  // Local Storage'a kaydetme
  useEffect(() => {
    localStorage.setItem('woorkzi-ideas', JSON.stringify(ideas));
    localStorage.setItem('woorkzi-tasks', JSON.stringify(tasks));
  }, [ideas, tasks]);

  // Local Storage'dan yükleme
  useEffect(() => {
    const savedIdeas = localStorage.getItem('woorkzi-ideas');
    const savedTasks = localStorage.getItem('woorkzi-tasks');
    
    if (savedIdeas) {
      setIdeas(JSON.parse(savedIdeas));
    }
    if (savedTasks) {
      setTasks(JSON.parse(savedTasks));
    }
  }, []);

  // Filtreleme fonksiyonu
  const getFilteredIdeas = () => {
    return ideas.filter(idea => {
      const matchesSearch = idea.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          idea.description.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCategory = filterCategory === 'all' || idea.category === filterCategory;
      const matchesStatus = filterStatus === 'all' || idea.status === filterStatus;
      const isTopLevel = !idea.parentId; // Sadece ana fikirleri göster
      
      return matchesSearch && matchesCategory && matchesStatus && isTopLevel;
    });
  };

  // Yeni fikir ekleme
  const handleAddIdea = (e) => {
    e.preventDefault();
    
    // Validasyon kontrolü
    const validation = validateIdea(newIdea);
    if (!validation.isValid) {
      setFormErrors(validation.errors);
      ToastManager.show('Lütfen form hatalarını düzeltin', 'error');
      return;
    }

    const idea = createNewIdea(
      newIdea.title.trim(),
      newIdea.description.trim(),
      newIdea.category,
      null
    );
    idea.priority = newIdea.priority;

    setIdeas(prev => [...prev, idea]);
    setNewIdea({ title: '', description: '', category: 'other', priority: 'medium' });
    setFormErrors({});
    setShowAddForm(false);
    
    ToastManager.show('Fikir başarıyla eklendi!', 'success');
  };

  // Alt fikir ekleme - Modal ile
  const handleAddSubIdea = (parentId) => {
    const parentIdea = ideas.find(idea => idea.id === parentId);
    setCurrentIdeaForModal(parentIdea);
    setShowSubIdeaModal(true);
  };

  const handleSubIdeaSubmit = (title, description) => {
    const parentId = currentIdeaForModal.id;
    const subIdea = createNewIdea(title, description, 'other', parentId);
    const newSubIdea = { ...subIdea, id: `subidea_${Date.now()}` };
    
    setIdeas(prev => {
      const updatedIdeas = [...prev, newSubIdea];
      return updatedIdeas.map(idea => 
        idea.id === parentId 
          ? { ...idea, subIdeas: [...idea.subIdeas, newSubIdea.id] }
          : idea
      );
    });
    
    ToastManager.show('Alt fikir başarıyla eklendi!', 'success');
  };

  // Görev ekleme - Modal ile
  const handleAddTask = (ideaId) => {
    const idea = ideas.find(idea => idea.id === ideaId);
    setCurrentIdeaForModal(idea);
    setShowTaskModal(true);
  };

  const handleTaskSubmit = (taskData) => {
    const ideaId = currentIdeaForModal.id;
    const task = createNewTask(taskData.title, taskData.description, ideaId);
    const newTask = { 
      ...task, 
      id: `task_${Date.now()}`,
      priority: taskData.priority,
      estimatedHours: taskData.estimatedHours
    };
    
    setTasks(prev => [...prev, newTask]);
    
    setIdeas(prev => prev.map(idea => 
      idea.id === ideaId 
        ? { ...idea, tasks: [...idea.tasks, newTask.id] }
        : idea
    ));
    
    ToastManager.show('Görev başarıyla eklendi!', 'success');
  };

  // Fikir kartını genişletme/daraltma
  const toggleExpandIdea = (ideaId) => {
    setExpandedIdea(expandedIdea === ideaId ? null : ideaId);
  };

  // Kategori rengi alma
  const getCategoryInfo = (categoryId) => {
    return categories.find(cat => cat.id === categoryId) || categories[categories.length - 1];
  };

  // Durum bilgisi alma
  const getStatusInfo = (statusId) => {
    return statusOptions.find(status => status.id === statusId) || statusOptions[0];
  };

  // Öncelik bilgisi alma
  const getPriorityInfo = (priorityId) => {
    return priorityOptions.find(priority => priority.id === priorityId) || priorityOptions[1];
  };

  // İstatistikler
  const stats = {
    total: ideas.length,
    active: ideas.filter(idea => idea.status === 'active').length,
    completed: ideas.filter(idea => idea.status === 'completed').length,
    inProgress: ideas.filter(idea => idea.status === 'in_progress').length
  };

  return (
    <div className="app">
      <div className="container">
        {/* Header */}
        <header className="header">
          <div className="app-title">
            <Lightbulb size={40} style={{ display: 'inline', marginRight: '15px', color: '#667eea' }} />
            Woorkzi
          </div>
          <p className="app-subtitle">
            Fikirlerinizi organize edin, projelerinizi hayata geçirin
          </p>
          
          {/* İstatistikler */}
          <div className="stats-container" style={{ 
            display: 'flex', 
            justifyContent: 'center', 
            gap: '30px', 
            marginTop: '20px',
            flexWrap: 'wrap'
          }}>
            <div className="stat-card" style={{ textAlign: 'center' }}>
              <div style={{ fontSize: '2rem', fontWeight: 'bold', color: '#667eea' }}>{stats.total}</div>
              <div style={{ fontSize: '0.9rem', color: '#6b7280' }}>Toplam Fikir</div>
            </div>
            <div className="stat-card" style={{ textAlign: 'center' }}>
              <div style={{ fontSize: '2rem', fontWeight: 'bold', color: '#3b82f6' }}>{stats.active}</div>
              <div style={{ fontSize: '0.9rem', color: '#6b7280' }}>Aktif</div>
            </div>
            <div className="stat-card" style={{ textAlign: 'center' }}>
              <div style={{ fontSize: '2rem', fontWeight: 'bold', color: '#8b5cf6' }}>{stats.inProgress}</div>
              <div style={{ fontSize: '0.9rem', color: '#6b7280' }}>Devam Eden</div>
            </div>
            <div className="stat-card" style={{ textAlign: 'center' }}>
              <div style={{ fontSize: '2rem', fontWeight: 'bold', color: '#10b981' }}>{stats.completed}</div>
              <div style={{ fontSize: '0.9rem', color: '#6b7280' }}>Tamamlandı</div>
            </div>
          </div>
        </header>

        {/* Arama ve Filtreler */}
        <div className="filters-section" style={{ 
          display: 'flex', 
          gap: '15px', 
          marginBottom: '30px',
          flexWrap: 'wrap',
          alignItems: 'center'
        }}>
          <div style={{ display: 'flex', alignItems: 'center', flex: '1', minWidth: '250px' }}>
            <Search size={20} style={{ color: '#6b7280', marginRight: '10px' }} />
            <input
              type="text"
              placeholder="Fikirlerinizi arayın..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="form-input"
              style={{ margin: 0 }}
            />
          </div>
          
          <select
            value={filterCategory}
            onChange={(e) => setFilterCategory(e.target.value)}
            className="form-select"
            style={{ minWidth: '150px' }}
          >
            <option value="all">Tüm Kategoriler</option>
            {categories.map(cat => (
              <option key={cat.id} value={cat.id}>{cat.icon} {cat.name}</option>
            ))}
          </select>

          <select
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value)}
            className="form-select"
            style={{ minWidth: '150px' }}
          >
            <option value="all">Tüm Durumlar</option>
            {statusOptions.map(status => (
              <option key={status.id} value={status.id}>{status.icon} {status.name}</option>
            ))}
          </select>

          <button
            onClick={() => setShowAddForm(!showAddForm)}
            className="btn btn-primary"
          >
            <Plus size={18} />
            Yeni Fikir
          </button>
        </div>

        {/* Yeni Fikir Ekleme Formu */}
        {showAddForm && (
          <div className="add-idea-section">
            <h3 style={{ marginBottom: '20px', color: '#374151' }}>
              <Plus size={20} style={{ marginRight: '8px', verticalAlign: 'middle' }} />
              Yeni Fikir Ekle
            </h3>
            
            <form onSubmit={handleAddIdea}>
              <div className="form-row">
                <div className="form-group">
                  <label>Başlık *</label>
                  <input
                    type="text"
                    value={newIdea.title}
                    onChange={(e) => {
                      setNewIdea(prev => ({ ...prev, title: e.target.value }));
                      if (formErrors.title) {
                        setFormErrors(prev => ({ ...prev, title: null }));
                      }
                    }}
                    className={`form-input ${formErrors.title ? 'error' : ''}`}
                    placeholder="Fikrinizin başlığını yazın..."
                    required
                  />
                  {formErrors.title && (
                    <div className="error-message">{formErrors.title}</div>
                  )}
                  <div className="char-count">
                    {formatCharCount(newIdea.title.length, 100).text}
                  </div>
                </div>
                <div className="form-group">
                  <label>Kategori</label>
                  <select
                    value={newIdea.category}
                    onChange={(e) => setNewIdea(prev => ({ ...prev, category: e.target.value }))}
                    className="form-select"
                  >
                    {categories.map(cat => (
                      <option key={cat.id} value={cat.id}>{cat.icon} {cat.name}</option>
                    ))}
                  </select>
                </div>
                <div className="form-group">
                  <label>Öncelik</label>
                  <select
                    value={newIdea.priority}
                    onChange={(e) => setNewIdea(prev => ({ ...prev, priority: e.target.value }))}
                    className="form-select"
                  >
                    {priorityOptions.map(priority => (
                      <option key={priority.id} value={priority.id}>{priority.icon} {priority.name}</option>
                    ))}
                  </select>
                </div>
              </div>
              
              <div className="form-group">
                <label>Açıklama</label>
                <textarea
                  value={newIdea.description}
                  onChange={(e) => setNewIdea(prev => ({ ...prev, description: e.target.value }))}
                  className="form-textarea"
                  placeholder="Fikrinizi detaylı olarak açıklayın..."
                  rows={3}
                />
              </div>
              
              <div style={{ display: 'flex', gap: '10px', justifyContent: 'flex-end' }}>
                <button
                  type="button"
                  onClick={() => setShowAddForm(false)}
                  className="btn btn-secondary"
                >
                  İptal
                </button>
                <button type="submit" className="btn btn-primary">
                  <Plus size={16} />
                  Fikir Ekle
                </button>
              </div>
            </form>
          </div>
        )}

        {/* Fikirler Listesi */}
        <div className="ideas-grid">
          {getFilteredIdeas().length === 0 ? (
            <div className="empty-state" style={{ gridColumn: '1 / -1' }}>
              <div className="empty-state-icon">💡</div>
              <h3 className="empty-state-title">Henüz Fikir Yok</h3>
              <p className="empty-state-description">
                İlk fikrinizi ekleyerek başlayın! Harika fikirler sizi bekliyor.
              </p>
            </div>
          ) : (
            getFilteredIdeas().map(idea => {
              const categoryInfo = getCategoryInfo(idea.category);
              const statusInfo = getStatusInfo(idea.status);
              const priorityInfo = getPriorityInfo(idea.priority);
              const isExpanded = expandedIdea === idea.id;
              const subIdeas = getSubIdeas(idea.id);
              const ideaTasks = getTasksByIdeaId(idea.id);

              return (
                <div
                  key={idea.id}
                  className={`idea-card ${isExpanded ? 'idea-expanded' : ''}`}
                  onClick={() => toggleExpandIdea(idea.id)}
                >
                  <div className="idea-header">
                    <div>
                      <h3 className="idea-title">{idea.title}</h3>
                      <div className="idea-meta">
                        <span className={`status-badge status-${idea.status}`}>
                          {statusInfo.icon} {statusInfo.name}
                        </span>
                        <span className={`priority-badge priority-${idea.priority}`}>
                          {priorityInfo.icon} {priorityInfo.name}
                        </span>
                        <span className="category-badge" style={{ 
                          backgroundColor: categoryInfo.color + '20',
                          color: categoryInfo.color 
                        }}>
                          {categoryInfo.icon} {categoryInfo.name}
                        </span>
                      </div>
                    </div>
                    <div>
                      {isExpanded ? <ChevronUp size={20} /> : <ChevronDown size={20} />}
                    </div>
                  </div>

                  <p className="idea-description">{idea.description}</p>

                  <div className="progress-bar">
                    <div 
                      className="progress-fill" 
                      style={{ width: `${idea.completionPercentage}%` }}
                    />
                  </div>

                  <div className="idea-stats">
                    <div className="stat-item">
                      <Calendar size={14} />
                      {new Date(idea.createdAt).toLocaleDateString('tr-TR')}
                    </div>
                    <div className="stat-item">
                      <Target size={14} />
                      %{idea.completionPercentage}
                    </div>
                    <div className="stat-item">
                      <Clock size={14} />
                      {idea.estimatedHours}sa
                    </div>
                  </div>

                  {/* Expanded Content */}
                  {isExpanded && (
                    <div className="expanded-content">
                      <div className="expanded-actions">
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            handleAddTask(idea.id);
                          }}
                          className="btn btn-success"
                        >
                          <Zap size={16} />
                          Görev Ekle
                        </button>
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            handleAddSubIdea(idea.id);
                          }}
                          className="btn btn-secondary"
                        >
                          <FolderPlus size={16} />
                          Alt Fikir Ekle
                        </button>
                      </div>

                      {/* Alt Fikirler */}
                      {subIdeas.length > 0 && (
                        <div className="sub-ideas">
                          <h4 style={{ marginBottom: '10px', color: '#374151' }}>
                            Alt Fikirler ({subIdeas.length})
                          </h4>
                          {subIdeas.map(subIdea => (
                            <div key={subIdea.id} className="sub-idea-item">
                              <div className="sub-idea-title">{subIdea.title}</div>
                              <div style={{ fontSize: '0.8rem', color: '#6b7280' }}>
                                {subIdea.description}
                              </div>
                            </div>
                          ))}
                        </div>
                      )}

                      {/* Görevler */}
                      {ideaTasks.length > 0 && (
                        <div className="tasks-list">
                          <h4 style={{ marginBottom: '10px', color: '#374151' }}>
                            Görevler ({ideaTasks.length})
                          </h4>
                          {ideaTasks.map(task => (
                            <div key={task.id} className="task-item">
                              <div className={`task-status task-${task.status.replace('_', '-')}`}></div>
                              <span>{task.title}</span>
                            </div>
                          ))}
                        </div>
                      )}

                      {/* Tags */}
                      {idea.tags.length > 0 && (
                        <div className="tags-container">
                          {idea.tags.map((tag, index) => (
                            <span key={index} className="tag">#{tag}</span>
                          ))}
                        </div>
                      )}
                    </div>
                  )}
                </div>
              );
            })
          )}
        </div>
      </div>

      {/* Modal'lar */}
      <AddSubIdeaModal
        isOpen={showSubIdeaModal}
        onClose={() => setShowSubIdeaModal(false)}
        onSubmit={handleSubIdeaSubmit}
        parentTitle={currentIdeaForModal?.title || ''}
      />

      <AddTaskModal
        isOpen={showTaskModal}
        onClose={() => setShowTaskModal(false)}
        onSubmit={handleTaskSubmit}
        ideaTitle={currentIdeaForModal?.title || ''}
      />
    </div>
  );
}

export default App;
